def fix_melakarta_intervals(apps, schema_editor):
    Melakarta = apps.get_model("lessons", "Melakarta")
    Ragam = apps.get_model("lessons", "Ragam")

    for number in range(1, 73):
        chakra_index = ((number - 1) // 6) % 6
        dn_index = (number - 1) % 6
        r, g = RG_VARIANTS[chakra_index]
        d, n = DN_VARIANTS[dn_index]
        m = 5 if number <= 36 else 6
        intervals = {"S": 0, "R": r, "G": g, "M": m, "P": 7, "D": d, "N": n}

        melakarta = Melakarta.objects.filter(number=number).first()
        if melakarta:
            melakarta.swara_intervals = intervals
            melakarta.save(update_fields=["swara_intervals"])

            # Also update the melakarta raga's arohanam/avarohanam
            ragam = Ragam.objects.filter(melakarta=melakarta, name=melakarta.name).first()
            if ragam:
                num = numbered_swaras(intervals)
                ragam.arohanam = (
                    f"S {num['R']} {num['G']} {num['M']} "
                    f"P {num['D']} {num['N']} S+"
                )
                ragam.avarohanam = (
                    f"S+ {num['N']} {num['D']} P {num['M']} "
                    f"{num['G']} {num['R']} S"
                )
                ragam.save(update_fields=["arohanam", "avarohanam"])


